from pathlib import Path


def replace_once(text, old, new, label):
    if new in text:
        return text
    if old not in text:
        raise RuntimeError(f'Patch anchor not found: {label}')
    return text.replace(old, new, 1)

# Android: make WebSocket reconnect ownership explicit and reset stale audio state on link loss.
p = Path('android/app/src/main/java/com/bwa3d/codexremote/RemoteService.java')
s = p.read_text(encoding='utf-8')

s = replace_once(s,
'''    private long lastWakeMs;\n    private String lastPartial = "";''',
'''    private long lastWakeMs;\n    private int reconnectAttempt;\n    private long socketGeneration;\n    private String lastPartial = "";''',
'android reconnect fields')

s = replace_once(s,
'''    private synchronized void connect() {\n        if (destroyed || serverIp == null) return;\n        if (socket != null) try { socket.cancel(); } catch (Exception ignored) { }\n        connected = false;\n        updateNotification("Conectando a " + serverIp + "…");\n        AndroidDebugLog.log("WS connecting ws://" + serverIp + ":" + serverPort + "/ws/");\n        socket = client.newWebSocket(new Request.Builder().url("ws://" + serverIp + ":" + serverPort + "/ws/").build(), new WebSocketListener() {\n            @Override public void onOpen(WebSocket webSocket, Response response) {\n                connected = true; socket = webSocket;\n                AndroidDebugLog.log("WS open");\n                sendText("{\\\"type\\\":\\\"hello\\\",\\\"name\\\":\\\"Android satellite\\\"}");\n                updateNotification(voskModel != null ? "Conectado · " + wakeWord() : "Conectado · preparando wake");\n                handler.post(RemoteService.this::startWakeRecognition);\n            }\n            @Override public void onMessage(WebSocket webSocket, String text) {\n                AndroidDebugLog.log("WS <- " + text);\n                handler.post(() -> handleServerMessage(text));\n            }\n            @Override public void onMessage(WebSocket webSocket, ByteString bytes) { playDownlink(bytes.toByteArray()); }\n            @Override public void onClosed(WebSocket webSocket, int code, String reason) {\n                AndroidDebugLog.log("WS closed code=" + code + " reason=" + reason);\n                connected = false; scheduleReconnect();\n            }\n            @Override public void onFailure(WebSocket webSocket, Throwable t, Response response) {\n                AndroidDebugLog.log("WS failure: " + t);\n                connected = false; updateNotification("Sin conexión · reintentando…"); scheduleReconnect();\n            }\n        });\n    }\n\n    private void scheduleReconnect() {\n        if (destroyed) return;\n        handler.removeCallbacks(reconnectRunnable);\n        handler.postDelayed(reconnectRunnable, 2500);\n    }\n    private final Runnable reconnectRunnable = () -> { if (!destroyed && !connected) connect(); };''',
'''    private synchronized void connect() {\n        if (destroyed || serverIp == null) return;\n        final long generation = ++socketGeneration;\n        WebSocket previous = socket;\n        socket = null;\n        if (previous != null) try { previous.cancel(); } catch (Exception ignored) { }\n        connected = false;\n        updateNotification("Conectando a " + serverIp + "…");\n        AndroidDebugLog.log("WS connecting gen=" + generation + " ws://" + serverIp + ":" + serverPort + "/ws/");\n        WebSocket created = client.newWebSocket(new Request.Builder().url("ws://" + serverIp + ":" + serverPort + "/ws/").build(), new WebSocketListener() {\n            private boolean current(WebSocket webSocket) { return generation == socketGeneration && socket == webSocket && !destroyed; }\n            @Override public void onOpen(WebSocket webSocket, Response response) {\n                if (generation != socketGeneration || destroyed) { try { webSocket.cancel(); } catch (Exception ignored) { } return; }\n                socket = webSocket; connected = true; reconnectAttempt = 0;\n                handler.removeCallbacks(reconnectRunnable);\n                AndroidDebugLog.log("WS open gen=" + generation);\n                sendText("{\\\"type\\\":\\\"hello\\\",\\\"name\\\":\\\"Android satellite\\\"}");\n                updateNotification(voskModel != null ? "Conectado · " + wakeWord() : "Conectado · preparando wake");\n                handler.post(RemoteService.this::startWakeRecognition);\n            }\n            @Override public void onMessage(WebSocket webSocket, String text) {\n                if (!current(webSocket)) return;\n                AndroidDebugLog.log("WS <- " + text);\n                handler.post(() -> { if (current(webSocket)) handleServerMessage(text); });\n            }\n            @Override public void onMessage(WebSocket webSocket, ByteString bytes) { if (current(webSocket)) playDownlink(bytes.toByteArray()); }\n            @Override public void onClosed(WebSocket webSocket, int code, String reason) {\n                if (!current(webSocket)) { AndroidDebugLog.log("Ignoring stale WS closed gen=" + generation); return; }\n                AndroidDebugLog.log("WS closed gen=" + generation + " code=" + code + " reason=" + reason);\n                handleSocketLost(webSocket);\n            }\n            @Override public void onFailure(WebSocket webSocket, Throwable t, Response response) {\n                if (!current(webSocket)) { AndroidDebugLog.log("Ignoring stale WS failure gen=" + generation + ": " + t); return; }\n                AndroidDebugLog.log("WS failure gen=" + generation + ": " + t);\n                handleSocketLost(webSocket);\n            }\n        });\n        socket = created;\n    }\n\n    private void handleSocketLost(WebSocket webSocket) {\n        if (socket != webSocket || destroyed) return;\n        connected = false;\n        socket = null;\n        handler.post(() -> {\n            handler.removeCallbacks(conversationTimeoutRunnable);\n            endingSession = false;\n            stopMicStreaming();\n            stopSpeaker();\n            stopResponseTranscriber();\n            if (overlay != null) overlay.hide();\n            updateNotification("Sin conexión · reintentando…");\n            scheduleReconnect();\n        });\n    }\n\n    private void scheduleReconnect() {\n        if (destroyed || connected) return;\n        handler.removeCallbacks(reconnectRunnable);\n        long delay = Math.min(8000L, 500L * (1L << Math.min(reconnectAttempt, 4)));\n        reconnectAttempt++;\n        AndroidDebugLog.log("WS reconnect scheduled in " + delay + " ms · attempt=" + reconnectAttempt);\n        handler.postDelayed(reconnectRunnable, delay);\n    }\n    private final Runnable reconnectRunnable = () -> { if (!destroyed && !connected) connect(); };''',
'android websocket reconnect')

p.write_text(s, encoding='utf-8')

# Windows: speed local text TTS to +25% using SSML.
p = Path('windows/CodexAudioRemote.Server/ContextAudioInjector.cs')
