# Windows: robust external-session handoff. Require a stable ready state, use UI busy state when exposed,
# and always use the selected safe downlink endpoint.
p = Path('windows/CodexAudioRemote.Server/ExternalConversationHub.cs')
s = p.read_text(encoding='utf-8')

s = replace_once(s,
'''        downlink?.Dispose();\n        downlink = new LoopbackDownlink(SendBinary);\n        await SendJson(new { type = "downlink_start", sampleRate = 16000, channels = 1 });\n        downlink.Start();\n\n        var becameBusy = await WaitMicAsync(false, 15000);\n        Console.WriteLine(becameBusy ? "Codex processing external context" : "No inactive transition detected; using readiness fallback");\n        var ready = await WaitMicAsync(true, 45000);\n        Console.WriteLine(ready ? "Codex ready after external context" : "Readiness timeout; opening Android mic as fallback");\n\n        downlink?.Dispose();\n        downlink = null;\n        switcher.MarkListening();\n        ExternalConversationHub.SetSuppressCodexEvents(false);\n        await SendJson(new { type = "codex_listening" });\n        Console.WriteLine("External conversation READY · Android microphone enabled");''',
'''        downlink?.Dispose();\n        downlink = new LoopbackDownlink(SendBinary, DownlinkDeviceSettings.SelectedDeviceId);\n        await SendJson(new { type = "downlink_start", sampleRate = 16000, channels = 1 });\n        downlink.Start();\n\n        var becameBusy = await WaitForBusyAsync(15000);\n        Console.WriteLine(becameBusy ? "Codex processing external context" : "No explicit busy transition detected; watching for stable ready state");\n        var ready = await WaitForStableReadyAsync(60000);\n        Console.WriteLine(ready ? "Codex stable-ready after external context" : "Stable-ready timeout; enabling Android mic as fallback");\n\n        downlink?.Dispose();\n        downlink = null;\n        switcher.MarkListening();\n        ExternalConversationHub.SetSuppressCodexEvents(false);\n        await Task.Delay(180, cts.Token);\n        await SendJson(new { type = "codex_listening", source = "external_context", readyConfirmed = ready });\n        Console.WriteLine("External conversation READY · Android microphone enabled");''',
'external handoff main')

insert_anchor = '''    async Task<bool> WaitMicAsync(bool desired, int timeoutMs)\n    {\n        var started = Environment.TickCount64;\n        while (!cts.IsCancellationRequested && Environment.TickCount64 - started < timeoutMs)\n        {\n            if (CodexMicDetector.IsActive() == desired) return true;\n            await Task.Delay(80, cts.Token);\n        }\n        return CodexMicDetector.IsActive() == desired;\n    }'''
insert_replacement = '''    async Task<bool> WaitMicAsync(bool desired, int timeoutMs)\n    {\n        var started = Environment.TickCount64;\n        while (!cts.IsCancellationRequested && Environment.TickCount64 - started < timeoutMs)\n        {\n            if (CodexMicDetector.IsActive() == desired) return true;\n            await Task.Delay(80, cts.Token);\n        }\n        return CodexMicDetector.IsActive() == desired;\n    }\n\n    async Task<bool> WaitForBusyAsync(int timeoutMs)\n    {\n        var started = Environment.TickCount64;\n        while (!cts.IsCancellationRequested && Environment.TickCount64 - started < timeoutMs)\n        {\n            var ui = CodexUiStateDetector.Detect();\n            if (!CodexMicDetector.IsActive() || ui.Busy) return true;\n            await Task.Delay(100, cts.Token);\n        }\n        return false;\n    }\n\n    async Task<bool> WaitForStableReadyAsync(int timeoutMs)\n    {\n        var started = Environment.TickCount64;\n        long readySince = 0;\n        const int StableMs = 700;\n        while (!cts.IsCancellationRequested && Environment.TickCount64 - started < timeoutMs)\n        {\n            var mic = CodexMicDetector.IsActive();\n            var ui = CodexUiStateDetector.Detect();\n            var candidate = mic && !ui.Busy;\n            var now = Environment.TickCount64;\n            if (candidate)\n            {\n                if (readySince == 0) readySince = now;\n                if (now - readySince >= StableMs) return true;\n            }\n            else readySince = 0;\n            await Task.Delay(100, cts.Token);\n        }\n        return false;\n    }'''
s = replace_once(s, insert_anchor, insert_replacement, 'external stable ready helpers')
p.write_text(s, encoding='utf-8')

print('Connection, TTS speed and HA handoff fixes ready for build')
